mapper.select:
SELECT a.`device_code` `deviceCode`, a.`statistical_flag` `statisticalFlag`, a.`statistical_cycle` `statisticalCycle`, a.`code` `code`, a.`shift_master` `shiftMaster`, a.`gear_position_code` `gearPositionCode`, a.`shift_master_phone` `shiftMasterPhone`, a.`department` `departmentName`, a.`gear_position_area` `gearPositionArea`, a.`unit_traffic` `unitTraffic`, a.`duration` `duration`, a.`flow` `flow`, a.`unit_price` `unitPrice`, a.`total` `total` FROM `water_data_month` a where 1=1
and a.`data_time` between #{param.startTime} and #{param.endTime}
and a.`department_id` like concat('%',#{param.departmentId},'%')
and a.`shift_master` like concat('%',#{param.shiftMaster},'%')
and a.`code` like concat('%',#{param.code},'%')
and a.`device_code` like concat('%',#{param.deviceCode},'%')
and a.`gear_position_code` like concat('%',#{param.gearPositionCode},'%')
and a.`duration` between #{param.duration.startDuration} and #{param.duration.endDuration}
and a.`flow` between #{param.flowParam.startFlow} and #{param.flowParam.endFlow}

SELECT a.`device_code` `deviceCode`, a.`statistical_flag` `statisticalFlag`, a.`statistical_cycle` `statisticalCycle`, a.`code` `code`, a.`shift_master` `shiftMaster`, a.`gear_position_code` `gearPositionCode`, a.`shift_master_phone` `shiftMasterPhone`, a.`department` `departmentName`, a.`gear_position_area` `gearPositionArea`, a.`unit_traffic` `unitTraffic`, a.`duration` `duration`, a.`flow` `flow`, a.`unit_price` `unitPrice`, a.`total` `total` FROM `water_data_month` a where 1=1
and a.`data_time` between #{param.startTime} and #{param.endTime}
and a.`department_id` like concat('%',#{param.departmentId},'%')
and a.`shift_master` like concat('%',#{param.shiftMaster},'%')
and a.`code` like concat('%',#{param.code},'%')
and a.`device_code` like concat('%',#{param.deviceCode},'%')
and a.`gear_position_code` like concat('%',#{param.gearPositionCode},'%')
and a.`duration` between #{param.duration.startDuration} and #{param.duration.endDuration}
and a.`flow` between #{param.flowParam.startFlow} and #{param.flowParam.endFlow}

SELECT `data_time` keyName,COUNT(distinct `code`) `value`  FROM `water_data_month` WHERE `duration` > 24

    and  `data_time` between #{startTime} and #{endTime}

GROUP BY `keyName`

SELECT ( a.`VALUE` / b.`VALUE` )*100 AS `VALUE`,a.`keyName` FROM ( SELECT `data_time` `keyName`, COUNT( DISTINCT `device_code` ) VALUE FROM `water_data_month` WHERE `duration` > 24
and `data_time` between #{startTime} and #{endTime}
GROUP BY `keyName` ) a LEFT JOIN ( SELECT `data_time` `keyName`, COUNT( DISTINCT `device_code` ) VALUE FROM `water_data_month` where 1=1
and `data_time` between #{startTime} and #{endTime}
GROUP BY `keyName` ) b ON a.`keyName` = b.`keyName`
